export const TACTIC_COUNT = TACTICS.length;

export const TECHNIQUE_COUNT = TACTICS.reduce((n, t) => n + t.techniques.length, 0);

export const SUBTECHNIQUE_COUNT = TACTICS.reduce(
  (n, t) => n + t.techniques.reduce((m, tech) => m + (tech.subTechniques?.length ?? 0), 0),
  0,
);

export function getTactic(slug: string): Tactic | undefined {
  return TACTICS.find((t) => t.slug === slug);
}

export function getAllTechniques(): TechniqueWithTactic[] {
  return TACTICS.flatMap((tactic) =>
    tactic.techniques.map((technique) => ({ ...technique, tactic })),
  );
}

export function getAllTechniquesAndSubs(): TechniqueWithTactic[] {
  return TACTICS.flatMap((tactic) =>
    tactic.techniques.flatMap((technique) => [
      { ...technique, tactic },
      ...(technique.subTechniques ?? []).map((sub) => ({ ...sub, tactic, parent: technique })),
    ]),
  );
}

export function getTechnique(id: string): TechniqueWithTactic | undefined {
  return getAllTechniquesAndSubs().find((t) => t.id === id);
}

export function getTechniqueIndex(id: string): number {
  return getAllTechniques().findIndex((t) => t.id === id);
}
